INSERT INTO device_deployment (
    device_tmpl_id, nav_node_id, face_plate_id, alarm_code, system_name, device_deploy_name,
    device_alias, n4_address, ip_address, mac_address, status, install_date,
    warranty_expire, location, department, responsible_person, contact_phone, extra_attrs
) VALUES (
    #{deviceTmplId}, #{navNodeId}, #{facePlateId}, #{alarmCode}, #{systemName}, #{deviceDeployName},
    #{deviceAlias}, #{n4Address}, #{ipAddress}, #{macAddress}, #{status}, #{installDate},
    #{warrantyExpire}, #{location}, #{department}, #{responsiblePerson}, #{contactPhone}, #{extraAttrs}
)

mapper.update:
UPDATE device_deployment
SET system_name = CONCAT('unmounted/', device_deploy_id),
    update_time = NOW()
WHERE system_name = #{systemName}
  AND device_deploy_name = #{deviceDeployName}
  AND (nav_node_id IS NULL OR is_deleted = 1)

UPDATE device_deployment
SET is_deleted = 1, update_time = NOW()
WHERE device_deploy_id = #{deviceDeployId}

UPDATE device_deployment
SET is_deleted = 0, update_time = NOW()
WHERE device_deploy_id = #{deviceDeployId}

UPDATE device_deployment
SET alarm_code = #{alarmCode}, update_time = NOW()
WHERE device_deploy_id = #{deviceDeployId}

UPDATE device_deployment
SET device_deploy_id = #{newDeviceId}, update_time = NOW()
WHERE device_deploy_id = #{oldDeviceId}
